// Node.js Runtime Architecture in action:
const fs = require('fs');
const crypto = require('crypto');

console.log("1. Executed purely in V8 Engine (Synchronous JS)");

// 2. Offloaded to libuv's Thread Pool (C++ level!)
crypto.pbkdf2('password', 'salt', 100000, 64, 'sha512', () => {
  console.log("3. Crypto hashing completed by libuv thread pool.");
});

// 4. Offloaded to the OS via libuv (Non-blocking I/O)
